const MAX_ATTEMPTS = 3;

async function deliver(post, url, event) {
  let attempts = 0;
  let res;
  do {
    res = await post(url, event);
    attempts += 1;
  } while (res.status >= 500 && attempts < MAX_ATTEMPTS);
  return { delivered: res.status < 300, attempts };
}

